<style>
.gs-page{--gs-border:var(--ws-line,#dfe5ed);--gs-card:var(--ws-panel,#fff);--gs-text:var(--ws-text,#182334);--gs-muted:var(--ws-muted,#667085)}
.gs-header{display:flex;justify-content:space-between;gap:16px;align-items:center;margin-bottom:22px}.gs-header h1{margin:0 0 7px;font-size:27px;color:var(--gs-text)}.gs-header p{margin:0;color:var(--gs-muted)}
.gs-form{display:grid;grid-template-columns:minmax(0,1.2fr) minmax(320px,.8fr);gap:20px;align-items:start}.gs-form.gs-form--single{grid-template-columns:minmax(0,900px)}.gs-panel{background:var(--gs-card);border:1px solid var(--gs-border);border-radius:16px;padding:24px;box-shadow:0 5px 30px #00000008;min-width:0}.gs-panel h2{font-size:17px;margin:0 0 20px;color:var(--gs-text)}
.gs-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:0 15px}.gs-field{display:grid;gap:7px;margin-bottom:15px;color:var(--gs-text);font-size:13px;font-weight:650}.gs-field input,.gs-field textarea,.gs-field select{width:100%;min-width:0;padding:12px 13px;border-radius:10px;background:var(--gs-card);color:var(--gs-text);border:1px solid var(--gs-border);font:inherit}.gs-field input:focus,.gs-field textarea:focus,.gs-field select:focus{outline:2px solid #5145e555;border-color:var(--primary,#5145e5)}.gs-field input[type=color]{height:46px;padding:6px;cursor:pointer}.gs-field input[type=file]{font-size:12px}
.gs-preview{display:block;width:100%;height:100px;object-fit:contain;border-radius:10px;border:1px dashed var(--gs-border);background:var(--ws-bg,#f7f8fb)}.gs-preview.banner{height:156px;object-fit:cover}.gs-preview.favicon{height:64px;width:96px}.gs-note{font-size:12px;color:var(--gs-muted);line-height:1.5;font-weight:400}.gs-save{border:0;color:#fff;background:var(--primary,#5145e5);padding:12px 22px;border-radius:10px;font-weight:750;cursor:pointer}.gs-save:hover{filter:brightness(1.08)}.gs-error,.gs-success{padding:12px;border-radius:9px;margin-bottom:16px}.gs-error{background:#fff1f2;color:#a11e32}.gs-success{background:#eaf8ee;color:#116537}.gs-section-label{font-size:12px;font-weight:700;letter-spacing:.06em;color:var(--gs-muted);text-transform:uppercase;margin-bottom:14px}.gs-actions{margin-top:20px}
@media(max-width:1024px){.gs-form{grid-template-columns:1fr}}@media(max-width:600px){.gs-panel{padding:16px}.gs-grid{grid-template-columns:1fr}.gs-header h1{font-size:23px}}
</style>
